describe('proof', function () {
  it('fails on the patched build', function () {
    // The parse regex must be anchored at the start: a string that does not
    // begin with an (optionally signed) number followed by a unit is invalid,
    // so parse() must fall back to parseInt(), which yields NaN and returns null.
    assert.strictEqual(bytes('foo 1kb'), null);
    assert.strictEqual(bytes('total: 512kb'), null);
  });
});

