describe('proof', function () {
  it('fails on the patched build', function () {
    assert.strictEqual(bytes.parse('10kb'), 10240);
    assert.strictEqual(bytes.parse('100mb'), 104857600);
    assert.strictEqual(bytes.parse('12.5kb'), 12800);
    assert.strictEqual(bytes.parse('-10kb'), -10240);
  });
});

