import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    // Explicitly tagged unsigned YAML 1.2 core octal must resolve.
    assert.strictEqual(load('!!int 0o777'), 511);
    assert.strictEqual(load('!!int 0o0'), 0);
    // Sanity checks: implicit octal and signed explicit octal are unaffected.
    assert.strictEqual(load('0o777'), 511);
    assert.strictEqual(load('!!int -0o777'), -511);
    assert.strictEqual(load('!!int 0xFF'), 255);
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('rejects non-string, non-number input with a throw', function () {
    // ms must throw for anything that is not a non-empty string or a
    // finite number. The patched build drops the typeof check, so an
    // array with a truthy length is passed to parse(), where
    // String(['100']) === '100' and the call returns 100 silently.
    assert.throws(function () {
      ms(['100']);
    }, /val is not a non-empty string or a valid number/);
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('uses the plural form at exactly 1.5 units in long format', function () {
    assert.strictEqual(ms(1500, { long: true }), '2 seconds');
    assert.strictEqual(ms(90000, { long: true }), '2 minutes');
    assert.strictEqual(ms(5400000, { long: true }), '2 hours');
    assert.strictEqual(ms(129600000, { long: true }), '2 days');
  });
});

